from paging import drop_head

def test_drop_all():
    assert drop_head([1, 2], 2) == []

def test_drop_zero():
    assert drop_head([1, 2], 0) == [1, 2]

def test_drop_one():
    assert drop_head([1, 2, 3], 1) == [2, 3]


